import sys

def readnums():
	return [int(x) for x in sys.stdin.readline().strip().split(' ')]
for i in range(readnums()[0]):
	intervals = []
	for j in range(readnums()[0]):
		intervals.append(readnums())
	intervals.sort()
	selected = []
	num_selected = 0
	while intervals:
		selected.append(intervals.pop())
		num_selected += 1
		if num_selected >= 2:
			if selected[-2][0] <= selected[-1][1]:
				overlap_int = [selected[-2][0], selected[-1][1]]
				intervals = list(filter(lambda interval: interval[1] < overlap_int[0], intervals))
	print(num_selected)
